      "path": "README.md",
      "content": "# dsh-wsl-defender\n\nDeepSeek Harness plugin: Windows security posture from WSL: Defender antivirus status and firewall profile state.\n\nPart of **[dsh-wsl-kit](https://github.com/173787247/dsh-wsl-kit)**.\n\n[中文说明 → README.zh.md](./README.zh.md)\n\n## Install\n\n```sh\ndsh plugin --profile web add github:173787247/dsh-wsl-defender\n```\n\n## Usage\n\n```\nwin_defender          # antivirus + firewall posture\n```\n\n## Notes\n\nUses `Get-MpComputerStatus` and `Get-NetFirewallProfile`. If Defender is\nmanaged by a third party, or the cmdlets are unavailable, the antivirus section reports\nunavailable rather than guessing.\n\n## Requirements\n\n- Windows with WSL, and DeepSeek Harness running inside it.\n\n## Tests\n\n```sh\nnpm test\n```\n\nThe unit tests run anywhere. The live tests are skipped outside WSL.\n\n## Compatibility\n\n| Field | Value |\n|-------|-------|\n| **Plugin** | `dsh-wsl-defender` **0.1.0** |\n| **Minimum dsh** | ≥ **0.1.2** (web UI one-shot `?token=` on Windows relay `:3081`) |\n| **Latest verified** | See [dsh-wsl-kit Compatibility](https://github.com/173787247/dsh-wsl-kit#compatibility-2026-09) (currently **`0.2.0-rc.2`**) — single source of truth for the suite |\n| **Kit set** | `full` or install alone |\n\n## License\n\nMIT\n"
    },
    {
      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-wsl-defender\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Windows security posture from WSL: Defender antivirus status and firewall profile state.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/173787247/dsh-wsl-defender.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/173787247/dsh-wsl-defender/issues\"\n  },\n  \"homepage\": \"https://github.com/173787247/dsh-wsl-defender#readme\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node --test test/*.test.js\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"wsl\",\n    \"windows\",\n    \"defender\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  }\n}\n"
    },
    {
      "path": "index.js",
      "content": "import { detectWsl } from \"./lib/wsl-host.js\";\nimport * as core from \"./lib/defender.js\";\nimport { execute } from \"./lib/defender-exec.js\";\n\nexport const name = \"dsh-wsl-defender\";\nexport const inject = [\"tools\", \"systemPrompt\"];\n\nexport function apply(ctx, config = {}) {\n  const wsl = detectWsl();\n\n  ctx.systemPrompt.section({\n    name: \"tool:win_defender\",\n    order: 218,\n    text: \"Use win_defender for WSL/Windows interop: Windows security posture from WSL: Defender antivirus status and firewall profile state.\",\n  });\n\n  ctx.tools.register({\n    name: \"win_defender\",\n    description: \"Windows security posture from WSL: Defender antivirus status and firewall profile state.\",\n    parameters: core.parameters(),\n    output: {\n      schema: core.outputSchema(),\n      render: (_args, value) => [{ type: \"text\", text: core.format(value) }],\n    },\n    timeoutMs: Number(config.timeoutMs) > 0 ? Number(config.timeoutMs) : 30_000,\n    isConcurrencySafe: () => true,\n    async execute(args) {\n      if (!wsl) return { ok: false, error: \"not running in WSL\" };\n      try {\n        return await execute(args, config);\n      } catch (error) {\n        return { ok: false, error: String(error?.message ?? error) };\n      }\n    },\n    presentCall: () => ({ card: \"generic\", title: \"win_defender\" }),\n    presentResult: (_args, result) => ({ card: \"generic\", title: \"win_defender\", content: result?.content }),\n  });\n}\n"
    }
